@'
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { parseManifest } from './packages/core/src/domain/manifest.ts';
import { parseSkillDocument, documentName, documentDescription } from './packages/core/src/domain/skill-document.ts';
const root = path.resolve('skills/executors-and-task-lifecycle');
const markdown = ['SKILL.md', 'references/shutdown-and-rejection.md', 'references/scheduled-and-periodic.md'];
const manifest = parseManifest(fs.readFileSync(path.join(root, 'skill.yaml'), 'utf8'), { strict: true });
assert.deepEqual(manifest.issues, []);
const document = parseSkillDocument(fs.readFileSync(path.join(root, 'SKILL.md'), 'utf8'));
assert.equal(documentName(document), manifest.manifest.name);
assert.equal(documentDescription(document), manifest.manifest.description);
assert.equal(manifest.manifest.version, '1.3.5');
for (const entry of manifest.manifest.files) assert.ok(fs.existsSync(path.join(root, entry)), entry);
const main = fs.readFileSync(path.join(root, 'SKILL.md'), 'utf8');
for (const reference of markdown.slice(1)) assert.ok(main.includes(reference), reference);
let localLinks = 0;
let anchors = 0;
for (const filename of markdown) {
  const text = fs.readFileSync(path.join(root, filename), 'utf8');
  for (const match of text.matchAll(/\[[^\]]*\]\(([^)]+)\)/g)) {
    const href = match[1];
    if (/^[a-z][a-z0-9+.-]*:/i.test(href)) continue;
    const [target, anchor] = href.split('#');
    const resolved = target ? path.resolve(root, path.dirname(filename), target) : path.join(root, filename);
    assert.ok(resolved.startsWith(root + path.sep), href);
    assert.ok(fs.existsSync(resolved), href);
    localLinks++;
    if (anchor) {
      const content = fs.readFileSync(resolved, 'utf8');
      const slugs = [...content.matchAll(/^#+\s+(.+)$/gm)].map(m => m[1].toLowerCase().replace(/[^a-z0-9\s-]/g, '').trim().replace(/\s+/g, '-'));
      assert.ok(slugs.includes(anchor), href);
      anchors++;
    }
  }
}
console.log(JSON.stringify({strictManifestIssues: manifest.issues.length, version: manifest.manifest.version, descriptionEqual: true, packageFileEntries: manifest.manifest.files.length, routedReferences: 2, localLinks, anchors}));
