import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

final class WorkerOwner {
    interface Client {
        void write(String value);
        void close();
    }
    private final Client client;
    private final AtomicBoolean accepting = new AtomicBoolean(true);
    private final AtomicInteger dropped = new AtomicInteger();
    private final ThreadPoolExecutor executor = new ThreadPoolExecutor(
            1, 1, 0, TimeUnit.MILLISECONDS, new ArrayBlockingQueue<>(1),
            new ThreadPoolExecutor.CallerRunsPolicy());

    WorkerOwner(Client client) { this.client = client; }

    void submit(String value) {
        if (!accepting.get()) throw new RejectedExecutionException("stopping");
        executor.execute(() -> client.write(value));
    }

    void stop() throws InterruptedException {
        accepting.set(false);
        executor.shutdown();
        if (!executor.awaitTermination(100, TimeUnit.MILLISECONDS)) {
            dropped.addAndGet(executor.shutdownNow().size());
            if (!executor.awaitTermination(2, TimeUnit.SECONDS)) {
                throw new IllegalStateException("residual workers; leave client open");
            }
        }
        client.close();
    }
}

